package com.search.extension;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import com.sun.net.httpserver.HttpServer;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;import org.springframework.data.domain.PageRequest;import org.springframework.test.util.ReflectionTestUtils;import org.springframework.web.reactive.function.client.WebClient;import com.search.extension.apiSearch.application.service.*;import com.search.extension.apiSearch.application.exception.ApiRequestsFailedException;
class ProviderLoopbackTest {
 @Test void actualHttpUsesOffsetAndBoundedTimeout()throws Exception{HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);java.util.List<String> urls=new java.util.concurrent.CopyOnWriteArrayList<>();ExecutorService pool=Executors.newCachedThreadPool();server.setExecutor(pool);server.createContext("/blog",exchange->{urls.add(exchange.getRequestURI().toString());if(exchange.getRequestURI().getQuery().contains("slow"))try{Thread.sleep(1000);}catch(InterruptedException ignored){}byte[] b="{\"lastBuildDate\":\"synthetic\",\"total\":100,\"start\":21,\"display\":0,\"items\":[]}".getBytes(StandardCharsets.UTF_8);exchange.getResponseHeaders().set("Content-Type","application/json");try{exchange.sendResponseHeaders(200,b.length);exchange.getResponseBody().write(b);}finally{exchange.close();}});server.start();try{NaverBlogSearchServiceImpl api=new NaverBlogSearchServiceImpl();ReflectionTestUtils.setField(api,"apiEndpoint","/blog");ReflectionTestUtils.setField(api,"naverApiWebClient",WebClient.create("http://127.0.0.1:"+server.getAddress().getPort()));ReflectionTestUtils.setField(api,"timeoutMillis",3000L);api.getApiSearchResults("page","accuracy",PageRequest.of(3,10));assertTrue(urls.get(0).contains("start=21"));ReflectionTestUtils.setField(api,"timeoutMillis",100L);assertTimeout(java.time.Duration.ofSeconds(2),()->assertThrows(RuntimeException.class,()->api.getApiSearchResults("slow","accuracy",PageRequest.of(1,10))));int count=urls.size();assertThrows(ApiRequestsFailedException.class,()->api.getApiSearchResults("page","accuracy",PageRequest.of(50,50)));assertEquals(count,urls.size());}finally{server.stop(0);pool.shutdownNow();}}
}
